import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>你的报名网站要求80KB。不是50KB，不是100KB，而是正好80KB。固定尺寸工具帮不上忙，猜一个画质设置也命中不了这个数字。</p>\n<p>目标文件大小压缩工具能解决这个问题。你输入精确的数字，工具会搜索能落在它以下一点点的最佳画质。</p>\n<p>这篇指南会走完整个流程，从读懂网站规则到验证完成后的文件。</p>\n<h2 id=\"what-you-need\">开始之前需要准备什么？</h2>\n<p>仔细读网站规则，写下精确的上限。记下数字、单位、格式，以及任何尺寸规则。</p>\n<p>拿到画质最高的原图。相机直出的照片最理想，通过聊天软件转发过的副本已经受损了。</p>\n<p>确认上限是最大值还是精确大小。大多数网站写的是最大值，低于这个数字的文件都能通过。</p>\n<p>原图单独放在一个文件夹里保存好。千万别用压缩版覆盖它，万一要重试还能找回来。</p>\n<h2 id=\"step-1-open\">第一步：打开目标压缩工具</h2>\n<p>在浏览器里打开<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩工具</a>。不需要账号，也不用安装。</p>\n<p>工具完全在你的设备上运行。照片在本地处理，永远不会上传到服务器。</p>\n<p>手机上操作也一样。点一下上传区域，从相册里选照片就行。</p>\n<p>如果你经常压缩到不寻常的尺寸，可以把页面加入收藏。这是固定尺寸工具服务不了的每个上限都能用的工具。</p>\n<h2 id=\"step-2-type-target\">第二步：输入精确的目标</h2>\n<p>把网站规则里的数字输入目标框。网站说80KB，就输入80，再选择KB。</p>\n<p>单位要仔细选。KB和MB差了一千倍，单位错了，做出来的文件就错得离谱。</p>\n<p>上传之前再检查一遍数字。这里打错字会浪费整次运行，因为工具会忠实地命中错误的目标。</p>\n<p>网站用MB表示上限时，比如1.5MB，就用MB输入。以后切换单位时，数字会自动重新计算。</p>\n<h2 id=\"step-3-upload\">第三步：上传图片</h2>\n<p>把文件拖到页面上，或者点一下浏览选择。支持JPG、PNG、WebP和HEIC，单个文件最大25MB。</p>\n<p>上传你手里画质最高的版本。1200万像素的原图能给压缩器留出大得多的发挥空间，小副本就不行。</p>\n<p>批量处理时，可以一次选多个文件。每张都会被压到同一个自定义目标，然后打包成ZIP下载。</p>\n<p>改设置之前，等上传完成。工具需要拿到完整的文件，才能搜索最佳画质。</p>\n<h2 id=\"step-4-format\">第四步：选择输出格式</h2>\n<p>照片用JPG是最安全的默认选择。它到处都被接受，任何自定义大小下压缩效率都很高。</p>\n<p>如果目的地接受WebP、而你又想要最锐利的结果，就选WebP。同样大小下，WebP的边缘会干净一点点。</p>\n<p>PNG只留给颜色扁平、线条锐利或带透明背景的图形。照片存成PNG，很难达到很紧的目标。</p>\n<p>图片带透明背景时，现在就决定要不要保留。转成JPG会把背景填满，通常是白色。</p>\n<h2 id=\"step-5-run\">第五步：运行压缩</h2>\n<p>工具会自动运行二分画质搜索。它会测试不同的画质档位，直到找到能塞进目标的最高画质。</p>\n<p>你不用自己选画质百分比。搜索会为你的这张图片找到最合适的数字。</p>\n<p>留意目标达成的确认信息。汇总会显示目标、实际达到的大小，以及每个文件是否通过。</p>\n<p>如果工具提示目标没达成，把格式换成JPG或者允许缩放尺寸，再跑一次。</p>\n<h2 id=\"step-6-preview\">第六步：仔细预览结果</h2>\n<p>下载之前，用全尺寸预览压缩后的图片。小缩略图会藏住问题，全尺寸下一眼就能看出来。</p>\n<p>先看细腻的细节。目标很紧时，脸部、文字和边缘是最先变柔和的地方。</p>\n<p>如果有对比视图，一定要用。原图和压缩版并排放在一起，细小的损伤最容易发现。</p>\n<p>按图片实际显示的尺寸来判断。放大到300%才看得见的缺陷，在正常尺寸下可能根本不重要。</p>\n<h2 id=\"step-7-download\">第七步：下载并验证</h2>\n<p>下载文件。文件名会标明自定义目标，不会和原图弄混。</p>\n<p>在设备上检查文件大小。它应该略低于你的目标，留出一点应对四舍五入的安全余量。</p>\n<p>确认格式符合网站规则。格式不对的完美文件，上传还是会失败。</p>\n<p>上传到网站并检查预览。提交表格之前，确认图片显示正确。</p>\n<h2 id=\"fixing-misses\">修复没达成的目标</h2>\n<p>目标没达成，通常只有三个原因：格式不对、尺寸被锁死，或者目标本身真的做不到。</p>\n<p>第一，把输出格式换成JPG。PNG格式的照片常常根本达不到很紧的目标。</p>\n<p>第二，允许缩放尺寸。工具会逐步减小像素尺寸，稍微缩一点，目标常常就解锁了。</p>\n<p>第三，裁掉空白或杂乱的边缘。背景杂乱的照片，会把KB浪费在没人看的地方。</p>\n<p>如果还是不行，再仔细读一遍网站规则。目标可能读错了，或者网站接受另一种格式。</p>\n<h2 id=\"batch-exact\">一次把批量压到精确大小</h2>\n<p>很多网站需要好几个文件都用同一个不寻常的大小。照片和签名都上限80KB，是很常见的一对。</p>\n<p>把所有文件加进同一个批量，用同一个目标。每个文件都会被单独搜索能塞进去的最佳画质。</p>\n<p>批量完成后检查汇总。它会显示哪些文件达成了目标、哪些没达成。</p>\n<p>没达成的单独修复。把出问题的文件拿出来，单独用不同的设置重新压缩。</p>\n<p>下载ZIP，解压到申请文件夹里。上传到网站之前，先给文件起好清楚的名字。</p>\n<h2 id=\"changing-target\">压缩后更改目标</h2>\n<p>不用重新上传文件就能更改目标。输入一个新数字，在同一批图片上再运行一次搜索。</p>\n<p>网站规则变了时，这很有用。昨天要80KB的表格，今天可能要120KB，重新跑一次只要几秒钟。</p>\n<p>一定要从原文件重新跑，而不是从压缩过的副本。每一轮压缩都会叠加损伤，所以要从新鲜的原图开始。</p>\n<p>选择之前，对比两张结果。更大的目标保留更多细节，所以要用网站允许的最大尺寸。</p>\n<h2 id=\"phone-workflow\">实战：手机上操作</h2>\n<p>在手机浏览器里打开工具，点一下上传区域。从相册里选原图。</p>\n<p>在小键盘上仔细输入目标。输错数字是手机上最常见的错误，所以要检查两遍。</p>\n<p>苹果手机的照片可能是HEIC格式。直接上传就行，工具会在压缩过程中完成转换。</p>\n<p>预览结果，再到“文件”应用里找到下载的文件。切回网站之前，确认大小略低于你的目标。</p>\n<h2 id=\"reading-portal-rules\">像检查清单一样读网站规则</h2>\n<p>网站规则藏在很长的说明页面里。像读检查清单一样读它，把重要的数字挑出来。</p>\n<p>提取四个事实：最大尺寸、单位、接受的格式，以及要求的尺寸。写在一行里。</p>\n<p>开始之前，把这一行和工具设置对比一下。这里不匹配，是上传被拒最常见的原因。</p>\n<p>留意隐藏的规则。有些网站限制的是所有上传文件的总和，而不是每个文件，这会完全改变计算方式。</p>\n<p>规则自相矛盾时，相信上传表格而不是帮助页面。真正检查你的文件的是表格。</p>\n<h2 id=\"odd-targets\">不寻常的目标：80KB、120KB、150KB</h2>\n<p>不寻常的目标很常见。网站会因为自己的存储原因选择80KB或150KB这样的数字，固定尺寸工具服务不了它们。</p>\n<p>80KB的人像比50KB的保留了明显更多的细节。头发和布料保存得更好，脸部看起来也更自然。</p>\n<p>150KB的博客图片处在100KB和200KB两个标准之间。对预算不寻常的主题来说，这是个合理的中间值。</p>\n<p>不要把不寻常的目标四舍五入到附近的固定尺寸。往下取会扔掉画质，往上取有被拒绝的风险。</p>\n<p>把这个不寻常的数字原样输入。工具就是为它设计的，搜索会为这个精确的目标找到最佳画质。</p>\n<h2 id=\"verifying-bytes\">按精确字节数验证结果</h2>\n<p>设备显示的文件大小是四舍五入到整KB的，藏住了精确的字节数。显示80KB的文件，实际可能是80.4KB。</p>\n<p>网站检查的是精确字节数。手机上看着没问题的文件，到了网站上可能因为几百字节而失败。</p>\n<p>相信工具自己的读数，而不是设备的读数。工具测量的是精确的字节数，并且会瞄准目标以下一点点。</p>\n<p>电脑上查看文件属性，能看到精确的字节数。把它和网站上限换算成的字节数对比一下。</p>\n<p>这个小检查能避免最让人沮丧的拒绝：一个到处都通过、唯独在网站上失败的文件。</p>\n<h2 id=\"signature-exact\">精确KB大小的签名</h2>\n<p>签名在精确目标下压起来非常漂亮。签名基本是白色空白，即使目标很紧，看起来依然干净。</p>\n<p>扫描签名时摆正，裁得紧一点。空白的边距会把目标预算浪费在空白纸上。</p>\n<p>用深色的笔在白纸上签名。浅浅的签名在压缩下会变虚，粗黑的墨水在任何大小下都保持锐利。</p>\n<p>压缩后用全尺寸预览签名。它应该看起来像纸上的墨水，而不是一团灰色的污渍。</p>\n<p>照片和签名共享同一个目标时，把它们一起批量处理。一次运行就能做出两个文件，做好了同一张表格的准备。</p>\n<h2 id=\"documents-exact\">精确KB大小的证件</h2>\n<p>证件混合了文字、印章，有时还有一张小照片。每个元素在压缩下的表现都不一样，这让精确目标变得棘手。</p>\n<p>300 DPI的扫描是最佳平衡。分辨率更高会造出巨大的文件，分辨率更低则会让文字变糊。</p>\n<p>压缩后预览最小的文字。注册号、日期和脚注是最先受损的地方。</p>\n<p>文字发虚时，试试WebP输出。同样大小下，它的小字比JPG更干净。</p>\n<p>每份证件都要留一份高分辨率的副本。网站以后可能要求更大的版本，而小文件没法干净地放大。</p>\n<h2 id=\"retry-strategy\">目标没达成时的重试策略</h2>\n<p>目标没达成时，一次只改一个地方。一下子全改了，就看不出来到底是哪个修复起了作用。</p>\n<p>第一，换成JPG格式。这一个改动能修复大多数没达成的情况，因为PNG通常是罪魁祸首。</p>\n<p>第二，允许缩放尺寸。小幅缩小常常能解锁目标，而且看不出损伤。</p>\n<p>第三，把图片裁得更紧一点。去掉空白或杂乱的边缘，主体就能分到更多的目标预算。</p>\n<p>三招都失败时，重新考虑目标。对这张图片来说，它可能真的做不到，更大的目标才是诚实的答案。</p>\n<h2 id=\"keeping-records\">记录精确目标</h2>\n<p>精确目标很容易忘。上个月要80KB的网站，这个月还是要80KB，而你不会记得这个数字。</p>\n<p>把目标和对应的网站记在一份简短的清单里。visa portal 80KB JPG这样的一句短注，能省掉每次重新读规则的麻烦。</p>\n<p>压缩文件和它所属的申请放在一起保存。visa-photo-80kb.jpg这样的文件名，本身就是说明。</p>\n<p>记下每个目标下哪些设置管用。一次通过的格式，下次还会通过，这句短注能省掉一次实验。</p>\n<p>好的记录能把精确目标从杂活变成常规操作。下一次申请几分钟就能完成，而不是一小时。</p>\n<h2 id=\"final-check-exact\">提交前的最后检查</h2>\n<p>确认设备上显示的文件大小略低于你的目标。找找工具在上限以下留出的那点安全余量。</p>\n<p>确认格式和尺寸符合网站规则。大小完美、格式不对的文件还是会上传失败，所以三个数字要一起检查。</p>\n<p>想看自定义目标的完整指南，可以读<a href=\"/zh/blog/mu-biao-wen-jian-da-xiao-ya-suo-qi-wan-zheng-zhi-nan/\">目标文件大小压缩工具：完整指南</a>。想深入了解搜索本身，可以看<a href=\"/zh/blog/jing-que-kb-mu-biao-er-fen-zhi-liang-sou-suo-jie-xi/\">精确KB目标：二分画质搜索详解</a>。固定尺寸合用时，<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB压缩工具</a>覆盖了最常见的上限。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"怎么把图片精确压到80KB？","answer":"打开目标文件大小压缩工具，输入80，选择KB，再上传图片。工具会运行二分画质搜索，找到能塞进80KB的最佳画质。下载结果，在设备上确认它略低于80KB。"},{"question":"网站要75KB，工具给了我73KB，这正常吗？","answer":"正常，而且是预期的。工具会故意瞄准目标以下一点点，留出安全余量，应对字节四舍五入的差异。设备上显示75KB的文件，实际可能是75.4KB，严格的网站会拒绝它。"},{"question":"能不重新上传图片就更改目标大小吗？","answer":"可以。输入新的目标数字，在同一批已上传的文件上再运行一次搜索。工具会从原始上传重新压缩，而不是从压缩过的副本，所以不会增加额外的损伤。"},{"question":"为什么80KB的目标失败了，100KB却成功了？","answer":"这张图片可能需要比80KB更多的数据，特别是细节丰富或尺寸被锁定的时候。换成JPG格式、允许缩放尺寸，或者把图片裁得更紧一点。还是失败的话，80KB的目标对这张图片来说可能真的做不到。"},{"question":"目标工具也支持MB大小吗？","answer":"支持。输入数字，再把单位选为MB。1.5MB的目标和80KB的工作方式一样，都是二分搜索找到能塞进去的最佳画质。切换单位时，数字会自动重新计算。"},{"question":"目标工具能用于透明PNG标志吗？","answer":"可以，但要保持WebP或PNG作为输出格式，才能保留透明背景。转成JPG会把透明区域填成白色。目标很紧时，WebP通常比PNG更容易达到。"}];
